def decide(recipient_reputation, round_num, my_history):
    # Default behavior for empty history
    if not my_history:
        return recipient_reputation > 0.0

    # Compute overall counts
    cooperations = sum(1 for act in my_history if act == 'cooperate')
    defections = len(my_history) - cooperations

    # Base threshold
    threshold = 0.2

    # Early rounds: be more cooperative
    if round_num < 5:
        threshold = 0.0

    # Adjust based on personal history balance
    if cooperations > defections:
        threshold = 0.4
    elif defections > cooperations:
        threshold = -0.1
    else:
        threshold = 0.2

    # Recent trend: last 5 actions (if available)
    if len(my_history) >= 5:
        recent = my_history[-5:]
        recent_coop = sum(1 for a in recent if a == 'cooperate')
        if recent_coop >= 4:
            threshold = 0.5
        elif recent_coop <= 1:
            threshold = -0.2

    return recipient_reputation > threshold
